import gc, sys
from src.service import stream_rows

class CleanupError(Exception): pass

class FailCloseRows:
    def __init__(self, rows, fail_read_at=None):
        self.rows=list(rows); self.i=0; self.closes=0; self.reads=0; self.fail_read_at=fail_read_at
    def read_next(self):
        self.reads += 1
        if self.fail_read_at is not None and self.reads == self.fail_read_at:
            raise RuntimeError("read failed")
        if self.i==len(self.rows): return None
        v=self.rows[self.i]; self.i+=1; return v
    def close(self):
        self.closes+=1
        raise CleanupError("close failed")

# 1. caller handling its own exception: exhaustion cleanup error must still propagate
try:
    1/0
except ZeroDivisionError:
    r = FailCloseRows([1])
    try:
        print("result:", list(stream_rows(r, lambda x: x)))
    except CleanupError as e:
